where id= #{id}

mapper.select:
select ifnull(count(*),0)
from `${tableName}`
where id = #{id}

select max(substring(screen_id,10,5)) as maxOrderNum
from tb_screen_person
where town=#{town}
and year =#{year}
and  screen_type=#{screenType}

