mapper.select:
SELECT sp.name
FROM tb_screen_point sp
LEFT JOIN system_users su ON sp.id = su.screen_point_id
WHERE su.id = #{id}
  AND su.deleted = 0;

SELECT sp.screen_dept
FROM tb_screen_point sp
LEFT JOIN system_users su ON sp.id = su.screen_point_id
WHERE su.id = #{id}
  AND su.deleted = 0;

